package com.antra.event;
import com.fasterxml.jackson.annotation.JsonAutoDetect; import jakarta.persistence.*; import java.math.BigDecimal; import java.time.*;
@Entity @Table(name="events") @JsonAutoDetect(fieldVisibility=JsonAutoDetect.Visibility.ANY) public class Event { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @Column(nullable=false) String title; @Column(nullable=false) String venue; @Column(nullable=false) Instant startsAt; @Column(nullable=false) BigDecimal price; @Column(nullable=false) int capacity; @Column(nullable=false) int availableTickets; @Column(nullable=false,length=2000) String description=""; String bannerUrl; @Version Long version; protected Event(){} Event(EventController.Create c){title=c.title();venue=c.venue();startsAt=c.startsAt();price=c.price();capacity=c.capacity();description=c.description();availableTickets=c.capacity();} }
